window.CONCEPTS=[{"group": "Axioms", "name": "Tools, not rules", "hits": [{"vid": "j1JRSan9CYg", "t": 595, "note": "No writing rules, only writing tools; mavens should not impose rules", "primary": true}], "dropped": 0}, {"group": "Axioms", "name": "No universal readers", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 450, "note": "No universal rules because no universal readers; Mark Manson's cheap words example", "primary": true}, {"vid": "OHfMQeZqo60", "t": 842, "note": "Be an anthropologist of reader language; no universal rules, focus on tools", "primary": true}], "dropped": 0}, {"group": "Axioms", "name": "Reader decides what good writing is", "hits": [{"vid": "qPb2659z8jQ", "t": 199, "note": "Good writing is a function of reader experience; the reader decides what good writing is", "primary": true}, {"vid": "iCaX5cZ6roo", "t": 421, "note": "Essays succeed on what readers already care about; readers decide what counts as understanding", "primary": false}, {"vid": "j1JRSan9CYg", "t": 533, "note": "Writing is a function not a thing; meaning arises in what readers do with the text", "primary": true}], "dropped": 0}, {"group": "Axioms", "name": "Value = solving a reader's problem", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 2129, "note": "Clear, organized, persuasive but useless is useless", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 514, "note": "Value, value, value: ask who cares before clarity; clear and useless is useless", "primary": true}, {"vid": "iTZt1_eocUg", "t": 1644, "note": "If readers cannot perceive a problem they cannot perceive value", "primary": true}, {"vid": "IOCOw72YjZk", "t": 1283, "note": "Ignore-readers advice assumes self-expression; clear and useless is useless", "primary": false}], "dropped": 0}, {"group": "Axioms", "name": "Change the reader's ideas, not express yours", "hits": [{"vid": "OHfMQeZqo60", "t": 362, "note": "Teachers assess what's in your head; real readers care about their own ideas and problems", "primary": true}], "dropped": 0}, {"group": "Axioms", "name": "Writing is thinking", "hits": [{"vid": "sHclRP3xJK8", "t": 699, "note": "Writing is thinking; university writing discovers ideas rather than reporting known ones", "primary": false}, {"vid": "Tgpx_04p2g8", "t": 374, "note": "Writing before ideas are formed lets them grow; belief X changes as you write", "primary": true}, {"vid": "hWHB2noYItY", "t": 247, "note": "Expert writing starts as thinking aloud, generating new knowledge", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 1961, "note": "If writing is thinking, knowing your conclusion beforehand kills discovery", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 361, "note": "Writing extends thinking so best ideas land at the end; can't give that to readers", "primary": false}, {"vid": "iCaX5cZ6roo", "t": 0, "note": "Writers use writing to work out a problem; solution comes at end", "primary": false}, {"vid": "OHfMQeZqo60", "t": 527, "note": "Learn what you think by writing; writer phase then reader-focused new draft", "primary": false}, {"vid": "OHfMQeZqo60", "t": 611, "note": "Two phases: writing as thinking, then a new reader-focused draft", "primary": false}, {"vid": "OHfMQeZqo60", "t": 1202, "note": "Iterative messy writing produces a new idea; value buried at the end", "primary": false}, {"vid": "VkXMlrvq29o", "t": 236, "note": "Alexis story: stringing words made solution appear; waiting to feel ready is a trap", "primary": true}, {"vid": "JGSA6Wbbaxo", "t": 1379, "note": "Writing as space of play and extension of thinking; discover rather than perform", "primary": false}, {"vid": "4nIo92ALrd0", "t": 571, "note": "Inquiry method is what writing is thinking means: question, evidence, discovery", "primary": true}, {"vid": "IOCOw72YjZk", "t": 962, "note": "Writing is how thinking becomes visible; thinking may happen elsewhere", "primary": false}, {"vid": "VrxufNaORhU", "t": 59, "note": "Christmas lights analogy: too tangled to sort in your head; write to untangle", "primary": false}, {"vid": "VrxufNaORhU", "t": 981, "note": "Expert writing solves open problems while generating text, so writing is not one act", "primary": false}, {"vid": "VrxufNaORhU", "t": 1214, "note": "Outlining first fails because writing extends thinking; let mind wander", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 358, "note": "Point refines as you move through the text in time", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Writer's draft vs reader draft", "hits": [{"vid": "Tgpx_04p2g8", "t": 144, "note": "Keep writing and rewriting separate; editing while producing is the trap", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 1474, "note": "Two different systems: writing to sort your confusion vs presenting to readers; first draft is yours", "primary": true}, {"vid": "jmUlhEAS6GE", "t": 2029, "note": "Reader draft starts from the reader's problem and subproblems, not from the writer's discovery", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 2094, "note": "Don't carry freewriting over; outline the reader's problems and position ideas as solutions", "primary": false}, {"vid": "kiIGwqwc49Q", "t": 505, "note": "First draft goes in a drawer; start a new reader's draft; strict distinction is liberating", "primary": true}, {"vid": "OHfMQeZqo60", "t": 475, "note": "Two functions of writing; phase one writing for yourself is valid but self-contained", "primary": false}, {"vid": "OHfMQeZqo60", "t": 611, "note": "Use writing as thinking first, then write a new reader-focused draft", "primary": false}, {"vid": "OHfMQeZqo60", "t": 1275, "note": "Interference: school never taught separating the two functions, which conflict in expert writing", "primary": false}, {"vid": "VkXMlrvq29o", "t": 729, "note": "Reader complaints describe friction between thinking and reading patterns; you cannot line-edit a writer's draft", "primary": true}, {"vid": "4nIo92ALrd0", "t": 1108, "note": "Phase one is thinking, phase two positions ideas for readers; mixing them causes paralysis", "primary": false}, {"vid": "VrxufNaORhU", "t": 284, "note": "Reader expectations let you transfer from the generating phase to the reader draft", "primary": false}, {"vid": "VrxufNaORhU", "t": 558, "note": "Writer's draft and reader draft are two separate documents; walk away once satisfied", "primary": true}], "dropped": 0}, {"group": "Two phases", "name": "Interference (writing vs reading patterns)", "hits": [{"vid": "jmUlhEAS6GE", "t": 1511, "note": "Writing patterns vs reading patterns: how you think interferes with how readers process", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 1591, "note": "Interference frustrates readers; writer patterns like chronology and background up front; rewrite completely", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 1794, "note": "Exhaustive completeness overwhelms readers who just want an answer to a question", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 4209, "note": "Remove writer-focused language: background, chronology, thought process; match reader process", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 258, "note": "Writers use text to solve a problem, readers to find ideas; restaurant directions example", "primary": true}, {"vid": "OHfMQeZqo60", "t": 1117, "note": "School writing habit creates reader problems called interference", "primary": false}, {"vid": "OHfMQeZqo60", "t": 1245, "note": "Writer thinks with text, reader learns from it; conflict of functions creates interference", "primary": false}, {"vid": "VkXMlrvq29o", "t": 669, "note": "Interference defined; readers say 'unclear'; you cannot line-edit a thinking draft into clarity", "primary": true}, {"vid": "VrxufNaORhU", "t": 0, "note": "Interference is the number one problem of expert writing: generating vs interpreting patterns", "primary": true}, {"vid": "VrxufNaORhU", "t": 284, "note": "Reader expectations are psychology not rules; readers are worst feedback source on drafts", "primary": false}, {"vid": "VrxufNaORhU", "t": 436, "note": "Dense/unclear feedback names symptom not cause; readers want stability to instability", "primary": false}, {"vid": "VrxufNaORhU", "t": 1095, "note": "Thinking draft is full of interference; fix with fractal index-and-discussion pattern", "primary": false}, {"vid": "VrxufNaORhU", "t": 1269, "note": "Don't think about reading patterns while generating; reverse outline indexes for coherence", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 802, "note": "Ordering paragraphs as they occurred to you is a writing pattern, not a reading pattern", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Artist and architect", "hits": [{"vid": "KSVv5SW2YU4", "t": 2122, "note": "Introduces shifting between artist (channel for ideas) and architect (sees how it hangs together)", "primary": true}, {"vid": "IOCOw72YjZk", "t": 1201, "note": "Begin as artist, revise as architect; the outline comes after or is inside the first draft", "primary": true}, {"vid": "IOCOw72YjZk", "t": 1386, "note": "Switching hats to architect means preparing text for readers; asks reader-focused questions", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Door closed / door open", "hits": [{"vid": "Tgpx_04p2g8", "t": 123, "note": "Write with the door closed for yourself, rewrite with it open for readers; keep them separate", "primary": true}], "dropped": 0}, {"group": "Two phases", "name": "Magma / volcano freewriting", "hits": [{"vid": "CXmMXFutuus", "t": 1337, "note": "Volcano metaphor: magma is unconscious creativity; freewriting pulls a bit up daily, no pressure", "primary": true}, {"vid": "CXmMXFutuus", "t": 1499, "note": "Magma cools into a shape in the bucket; sort it later, you cannot sculpt magma", "primary": true}, {"vid": "CXmMXFutuus", "t": 1797, "note": "Freewriting makes the flow state reliable; 90 percent trash, write raw then shape", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Coffee stain problem", "hits": [{"vid": "bBg7GyIfn0A", "t": 0, "note": "Defines the coffee stain problem: your words trigger your memory, association not communication", "primary": true}, {"vid": "mQ02Vwg-Uuo", "t": 0, "note": "Previews the coffee stain problem as why clear-in-your-head ideas confuse readers", "primary": false}, {"vid": "mQ02Vwg-Uuo", "t": 109, "note": "Full thought experiment: stained page reminds you of the idea, means nothing to readers", "primary": true}, {"vid": "mQ02Vwg-Uuo", "t": 614, "note": "Links private structure (mother's phone number) to the coffee stain problem and metadiscourse", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Briefed reader (Carnegie Mellon study)", "hits": [{"vid": "6HPNb0tiDNg", "t": 223, "note": "You are always the briefed reader of your own draft, so you can't interpret it cold", "primary": true}], "dropped": 0}, {"group": "Two phases", "name": "Directions to the restaurant", "hits": [{"vid": "bBg7GyIfn0A", "t": 317, "note": "Restaurant analogy: writers describe their own route instead of the reader's; writing vs reading patterns", "primary": true}, {"vid": "VkXMlrvq29o", "t": 581, "note": "Skipping the reverse outline is like giving your friend your own route to the restaurant", "primary": false}, {"vid": "VrxufNaORhU", "t": 618, "note": "Writer's draft is like telling a friend the steps you took to reach the restaurant", "primary": true}], "dropped": 0}, {"group": "Two phases", "name": "Christmas lights / tangled expertise", "hits": [{"vid": "VkXMlrvq29o", "t": 375, "note": "Expert knowledge is tangled Christmas lights; you see connections only by untangling", "primary": true}, {"vid": "VrxufNaORhU", "t": 59, "note": "Christmas lights metaphor: first phase of writing untangles thinking too complex for the head", "primary": true}, {"vid": "VrxufNaORhU", "t": 1269, "note": "Reverse outline: unlabeled parts are still a tangled knot of Christmas lights", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Reverse outline", "hits": [{"vid": "VkXMlrvq29o", "t": 491, "note": "Write to think, then use the reverse outline to keep drafts from becoming spaghetti", "primary": true}, {"vid": "VkXMlrvq29o", "t": 581, "note": "Label each section after drafting; reverse outline is step two of the expert process", "primary": false}, {"vid": "VrxufNaORhU", "t": 1153, "note": "Skim test: highlight index positions and check they tell a coherent story", "primary": true}, {"vid": "VrxufNaORhU", "t": 1269, "note": "Draw section lines, mark each index, read only indexes; unlabeled parts are fluff", "primary": false}], "dropped": 0}, {"group": "Two phases", "name": "Skim test", "hits": [{"vid": "2ToJcKiQWBc", "t": 709, "note": "Skim test: skim the index of each paragraph and see if it tells a coherent story", "primary": true}, {"vid": "VrxufNaORhU", "t": 1153, "note": "Skim test as diagnostic: highlight index positions as storyboard, amounts to reverse outline", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Timed freewriting / non-editing", "hits": [{"vid": "Tgpx_04p2g8", "t": 144, "note": "Separate writing from editing; practice non-editing: 15-minute timer, no backspacing", "primary": true}, {"vid": "Tgpx_04p2g8", "t": 267, "note": "Block distractions; keep writing and editing distinct, save editing for later", "primary": false}, {"vid": "Tgpx_04p2g8", "t": 330, "note": "Writing without editing lets ideas grow; stop being embarrassed by stupid ideas", "primary": false}, {"vid": "Tgpx_04p2g8", "t": 600, "note": "Stuck? pretend you're speaking, timer, or switch to voice-to-text; don't force it", "primary": false}, {"vid": "Tgpx_04p2g8", "t": 877, "note": "After the timer, summarize standout ideas; 10-15 minute focused freewrite on one idea", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 2094, "note": "Freewriting session discovers knowledge; reader draft then outlines reader problems", "primary": false}, {"vid": "kiIGwqwc49Q", "t": 372, "note": "20-minute timer brain dump daily; morning pages with your question at the top", "primary": true}, {"vid": "KSVv5SW2YU4", "t": 607, "note": "Focus on completing sessions; Seinfeld timer practice", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 1242, "note": "EFL fluency drill: set a timer and write anything, even 'I don't know what to write'", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 2233, "note": "Freewrite then hunt for strongest thoughts; revision is writing", "primary": false}, {"vid": "VkXMlrvq29o", "t": 400, "note": "Morning brain dump with question at top and timer; drafts as excavation sites", "primary": false}, {"vid": "VkXMlrvq29o", "t": 537, "note": "Step one timed brain dump; step two label each section", "primary": false}, {"vid": "CXmMXFutuus", "t": 1337, "note": "Freewriting as pulling magma to surface; no pressure to be meaningful", "primary": true}, {"vid": "CXmMXFutuus", "t": 1499, "note": "Magma cools into a shape you don't choose; freewriting isn't for anybody", "primary": false}, {"vid": "CXmMXFutuus", "t": 1673, "note": "Can't sculpt magma; review freewriting later with random note resurfacing", "primary": false}, {"vid": "CXmMXFutuus", "t": 1797, "note": "Freewriting makes the flow state reliable; 90% trash, 10% better than planned", "primary": false}, {"vid": "IOCOw72YjZk", "t": 991, "note": "Artist phase: set a timer and write without direction; nobody will read it", "primary": false}], "dropped": 0}, {"group": "Process", "name": "Placeholders while drafting", "hits": [{"vid": "Tgpx_04p2g8", "t": 181, "note": "When stuck during timed writing, use placeholders instead of stopping", "primary": false}, {"vid": "Tgpx_04p2g8", "t": 554, "note": "Placeholder phrases like 'the thing is' or 'what I'm trying to say is' to push through", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Question at the top of the page / tether", "hits": [{"vid": "kiIGwqwc49Q", "t": 420, "note": "Morning pages variant: write your question at the top, freewrite 10-20 minutes", "primary": true}, {"vid": "VkXMlrvq29o", "t": 400, "note": "Daily brain dump with a question at top of page; early drafts are excavation sites", "primary": false}, {"vid": "IOCOw72YjZk", "t": 1049, "note": "Question at top of page as tether to return to when lost while freewriting", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Question, not topic", "hits": [{"vid": "4nIo92ALrd0", "t": 279, "note": "Question is your filter for evidence; holds conclusion in suspension", "primary": true}, {"vid": "4nIo92ALrd0", "t": 444, "note": "Inquiry method step one: start with a question, which filters evidence", "primary": false}, {"vid": "ED_LXx3Hzak", "t": 167, "note": "Topic gives pile of things to say; question gives reason; solar panel example", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Inquiry method (evidence + reasoning = claim)", "hits": [{"vid": "hWHB2noYItY", "t": 816, "note": "Truth claims demand evidence and reasoning; ask what the core idea is and who disagrees", "primary": false}, {"vid": "4nIo92ALrd0", "t": 400, "note": "Introduces inquiry method as scientific method for values; step one question, step two evidence", "primary": true}, {"vid": "4nIo92ALrd0", "t": 509, "note": "Evidence plus reasoning equals claim; disagreement targets evidence or reasoning", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Reading is food, not fuel", "hits": [{"vid": "VkXMlrvq29o", "t": 195, "note": "Reading is food for hungry writing: read when you hit a wall, guided by a question", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Virtuous procrastination", "hits": [{"vid": "Tgpx_04p2g8", "t": 313, "note": "Separate producing from perfecting; editing often becomes virtuous procrastination", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 1545, "note": "Cleaning and important-feeling work as guilt-free avoidance when writing terrifies you", "primary": true}, {"vid": "KSVv5SW2YU4", "t": 2339, "note": "Research counts as writing if it moves the project; otherwise it's avoidance", "primary": false}], "dropped": 0}, {"group": "Process", "name": "Writer's block as fear", "hits": [{"vid": "KSVv5SW2YU4", "t": 0, "note": "Resistance or writer's block called by its true name, fear; eight tips promised", "primary": true}, {"vid": "KSVv5SW2YU4", "t": 1914, "note": "Fear signals you're near the truth; ask what scares you and write toward it", "primary": true}, {"vid": "4nIo92ALrd0", "t": 1108, "note": "Blending the two writing phases and thinking of readers too soon causes block", "primary": false}, {"vid": "CXmMXFutuus", "t": 0, "note": "Writer's block as a sign of breakthrough; discipline made his year-long block worse", "primary": true}, {"vid": "CXmMXFutuus", "t": 646, "note": "Block is pent-up energy unable to reach your persona; the fix is getting out of the way", "primary": false}, {"vid": "CXmMXFutuus", "t": 729, "note": "Protective layers block creative energy; let yourself die for the work to live", "primary": false}, {"vid": "CXmMXFutuus", "t": 959, "note": "Elephant and rider: block means the elephant no longer wants your project", "primary": false}, {"vid": "IOCOw72YjZk", "t": 925, "note": "Writing from an outline often led him into writer's block; brief mention", "primary": false}, {"vid": "gaqIcDkTakA", "t": 0, "note": "Is writer's block a writing problem or missing someone to talk to?", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1839, "note": "You never have writer's block when you're talking to somebody", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1919, "note": "Knowing and liking your reader makes voice and block problems vanish", "primary": false}], "dropped": 0}, {"group": "Process", "name": "Writing anorexia / don't cut early", "hits": [{"vid": "KSVv5SW2YU4", "t": 2059, "note": "Concision advice too early is writing anorexia; cut only when you have plenty; artist then architect", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Elephant and rider / night shift (unconscious)", "hits": [{"vid": "CXmMXFutuus", "t": 826, "note": "Elephant and rider metaphor for unconscious; writer's block; night shift and Kekule dream", "primary": true}, {"vid": "CXmMXFutuus", "t": 1146, "note": "Explains night shift: unconscious older than language, speaks in images and hunches", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Lacan: Imaginary, Symbolic, Real", "hits": [{"vid": "CXmMXFutuus", "t": 336, "note": "Lacan's three registers explained: Imaginary self-image, Symbolic masks, Real behind closed doors", "primary": true}, {"vid": "CXmMXFutuus", "t": 493, "note": "Imaginary and Symbolic pile on the Real; writer's block is blocked jouissance; get out of the way", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Aim low / small daily goals", "hits": [{"vid": "Tgpx_04p2g8", "t": 181, "note": "Set a 15-minute timer for 250 words: one sentence a minute is easy", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 607, "note": "Drop word-count obsession; aim for two pages a day or just complete the session", "primary": false}, {"vid": "KSVv5SW2YU4", "t": 709, "note": "Arithmetic: 10 words a minute in 25-minute sessions adds up to a book draft", "primary": true}, {"vid": "KSVv5SW2YU4", "t": 817, "note": "Jordan Peterson's 'aim low': small attainable daily goals compound; unmet goals don't build habits", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Wile E. Coyote rule", "hits": [{"vid": "KSVv5SW2YU4", "t": 2011, "note": "Write your best idea down immediately, don't save it; forces you to find a better ending", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Zettelkasten / fleeting, literature, permanent notes", "hits": [{"vid": "VkXMlrvq29o", "t": 400, "note": "Daily fleeting note brain dump with a question on top; drafts as excavation sites", "primary": false}, {"vid": "_ribgj7VIGc", "t": 180, "note": "Fleeting notes folder captures sources from life, voice memos, and dreams", "primary": false}, {"vid": "_ribgj7VIGc", "t": 396, "note": "Fleeting note with auto timestamp ID catches experience without friction", "primary": false}, {"vid": "_ribgj7VIGc", "t": 492, "note": "Literature note is marginalia, a dialogue with the text, not highlights or summary", "primary": true}, {"vid": "_ribgj7VIGc", "t": 637, "note": "Permanent note is one atomic idea in your words, linked to source and another note", "primary": true}, {"vid": "_ribgj7VIGc", "t": 737, "note": "Three note types compared; permanent notes link into a web, IDs prevent orphans", "primary": true}, {"vid": "_ribgj7VIGc", "t": 830, "note": "Patterns emerge across permanent notes; Lacan and Deutsch link; names the Zettelkasten method", "primary": false}, {"vid": "_ribgj7VIGc", "t": 1403, "note": "Recap of the habit from fleeting to literature to permanent notes with AI navigation", "primary": false}], "dropped": 0}, {"group": "Process", "name": "Copy work / steal style", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 1729, "note": "Steal style exercise: read admired passage, close book, rewrite it from memory", "primary": true}, {"vid": "0-YMN4Z-H_0", "t": 796, "note": "Copy work from copywriting: copy exceptional writing out from memory to learn structure", "primary": true}], "dropped": 0}, {"group": "Process", "name": "Great Sentences Mad Libs", "hits": [{"vid": "vFsQgIQFtwM", "t": 489, "note": "Introduces Great Sentences Mad Libs: practice form not content, demonstrated with Jabberwocky", "primary": true}, {"vid": "vFsQgIQFtwM", "t": 608, "note": "Mad Libs as writer's scales; practicing forms produces new sentences, DeLillo's sentence sculpting", "primary": false}], "dropped": 0}, {"group": "Process", "name": "Sentence bird-watching / collect sentences", "hits": [], "dropped": 0}, {"group": "Reader", "name": "Know your reader / four reader questions", "hits": [{"vid": "bBg7GyIfn0A", "t": 181, "note": "Four reader questions: motivation, problem, answer sought, decision; builds reader profile", "primary": true}, {"vid": "iCaX5cZ6roo", "t": 0, "note": "Contrasts 'write for yourself' with knowing the reader; writing as thinking vs shipping", "primary": false}, {"vid": "IOCOw72YjZk", "t": 1228, "note": "Discusses Housel calling 'know your reader' the worst advice; why it sounds liberating", "primary": false}], "dropped": 0}, {"group": "Reader", "name": "Uninformed, indifferent, resistant readers", "hits": [{"vid": "bBg7GyIfn0A", "t": 650, "note": "Three reader types and what each needs: background, consequences, or acknowledging their position", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Rhetorical planning wheel / situational network", "hits": [{"vid": "UqiEjaCiWmQ", "t": 428, "note": "Introduces rhetorical planning wheel: genre and actions at center, situational network around", "primary": true}, {"vid": "UqiEjaCiWmQ", "t": 612, "note": "Mapping cause-and-effect context forms the situational network; text must match context", "primary": true}, {"vid": "UqiEjaCiWmQ", "t": 785, "note": "Blending exercise: anchor your mapped network in the classic scene of shared attention", "primary": false}], "dropped": 0}, {"group": "Reader", "name": "Joint attention / classic scene / blending", "hits": [{"vid": "UqiEjaCiWmQ", "t": 164, "note": "Defines joint attention: two people attending to a blackbird share the same mental context", "primary": true}, {"vid": "UqiEjaCiWmQ", "t": 612, "note": "Anchor a complex situational network in the classic scene via blending; Jane Austen letter, exercise", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Code words / secret language / value words", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 357, "note": "Use in-group code words that carry special meaning for readers, not fifth-grade level", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 964, "note": "Learn readers' secret language: hunt value-coded words in prominent texts like an anthropologist", "primary": true}, {"vid": "jmUlhEAS6GE", "t": 2960, "note": "Creating value starts with mastering the code words that signal importance", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 3253, "note": "Editing exercise: circle value words; expect them front-loaded and in every paragraph opener", "primary": false}, {"vid": "qPb2659z8jQ", "t": 472, "note": "Annotates HBR opening: red words are value words readers instantly recognize", "primary": false}, {"vid": "qPb2659z8jQ", "t": 1892, "note": "Universal value signals like 'but' plus community-specific code words found by studying popular pieces", "primary": false}, {"vid": "VkXMlrvq29o", "t": 955, "note": "Code words as secret handshake; value is in the reader; how to hunt community-specific words", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Anthropologist exercise (mine community texts)", "hits": [{"vid": "jmUlhEAS6GE", "t": 1101, "note": "Value-coded words like however, critical, enables; be an anthropologist of your field's language", "primary": false}, {"vid": "qPb2659z8jQ", "t": 1892, "note": "Pick four or five popular pieces for your readers and mine them for in-group code words", "primary": true}, {"vid": "OHfMQeZqo60", "t": 842, "note": "Examine language patterns shared by target readers; adjust register, no universal rules", "primary": false}, {"vid": "VkXMlrvq29o", "t": 1077, "note": "Scan community cultural artifacts (e.g. HBR) for code words; Arthur's X-ray vision on audience", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Problem statement template (topic/question/benefit)", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 2200, "note": "Fill-in problem statement: writing about topic to find out question to help reader gain benefit", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Two-player game / genre as functions", "hits": [{"vid": "kiIGwqwc49Q", "t": 0, "note": "Writing is like chess or tennis: watch the other player's moves, treat it as two-player", "primary": false}, {"vid": "kiIGwqwc49Q", "t": 1028, "note": "Starbucks ordering as a genre: consistent functions, not templates; favorite-color question breaks it", "primary": true}, {"vid": "kiIGwqwc49Q", "t": 1369, "note": "Plan the piece as moves and reader responses, starting with a greeting function", "primary": false}, {"vid": "OHfMQeZqo60", "t": 582, "note": "Put ideas where readers expect them by reproducing your genre's language patterns", "primary": false}, {"vid": "OHfMQeZqo60", "t": 1245, "note": "Writer uses text to think, reader to learn; mismatch of functions creates interference", "primary": false}], "dropped": 0}, {"group": "Reader", "name": "Enter the conversation politely", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 1053, "note": "To be accepted, take interest in prior work and show deference to the big names", "primary": false}, {"vid": "G-Sl0-PZv2Q", "t": 1089, "note": "Writing is entering a conversation; contribute to an ongoing problem with concern for reader", "primary": true}, {"vid": "jmUlhEAS6GE", "t": 2299, "note": "To use writing socially, modulate claims and show deference even when you disagree", "primary": true}], "dropped": 0}, {"group": "Reader", "name": "Audience capture", "hits": [{"vid": "4nIo92ALrd0", "t": 1055, "note": "Why 'obsess over readers' advice sounds like audience capture, a degraded slave-to-interests writing", "primary": false}, {"vid": "4nIo92ALrd0", "t": 1174, "note": "Skip phase one (own thinking) and you get audience capture; skip phase two and nobody reads", "primary": true}, {"vid": "IOCOw72YjZk", "t": 1250, "note": "Fiction's 'ignore readers' advice misapplied to nonfiction; fear of audience capture", "primary": false}], "dropped": 0}, {"group": "Reader", "name": "Expressionist vs rationalist / positivist", "hits": [{"vid": "2ToJcKiQWBc", "t": 467, "note": "Expressionist framework assumes ideas valuable because expressed; rationalist values usefulness", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 978, "note": "Summing up in conclusions reflects positivist mentality that information alone is valuable", "primary": false}], "dropped": 0}, {"group": "Reader", "name": "Knowledge as puzzle vs model; the gap model", "hits": [{"vid": "iCaX5cZ6roo", "t": 342, "note": "Knowledge as fixed puzzle vs idea as invention taken to market; facts vs judgment", "primary": true}, {"vid": "OHfMQeZqo60", "t": 874, "note": "Explains the gap model and why 'nobody has studied this' is not value; McCarthy archive example", "primary": true}, {"vid": "OHfMQeZqo60", "t": 1072, "note": "Gap model yields content that is new but not valuable without utility", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Problem framework (status quo, concession, destabilizing condition, cost, solution)", "hits": [{"vid": "jmUlhEAS6GE", "t": 2333, "note": "Status quo, concession, then destabilizing condition; concede value before dismantling consensus", "primary": true}, {"vid": "qPb2659z8jQ", "t": 494, "note": "Walks HBR opening: status quo, concession, 'still', then destabilizing condition overturns it", "primary": true}, {"vid": "qPb2659z8jQ", "t": 677, "note": "After destabilizing condition come consequence and solution; the five pieces of a problem", "primary": false}, {"vid": "iTZt1_eocUg", "t": 1672, "note": "Framework: status quo as opposite of thesis, concession, then 'but' destabilizing condition", "primary": true}, {"vid": "ePQoPNHZ7UY", "t": 292, "note": "Establish common ground readers accept before flipping it; George Mack example", "primary": false}, {"vid": "ePQoPNHZ7UY", "t": 463, "note": "Three steps for status quo: invert idea, state it plainly, set up the contrast", "primary": false}, {"vid": "ePQoPNHZ7UY", "t": 574, "note": "Problem has two parts: condition showing what is wrong and consequence or cost", "primary": false}, {"vid": "ePQoPNHZ7UY", "t": 892, "note": "Three-part formula: status quo, problem made of condition and consequence, solution", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 424, "note": "Introduction has three parts: common ground, problem, solution positioning your idea", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Condition + consequence; the 'so what?' test", "hits": [{"vid": "jmUlhEAS6GE", "t": 4050, "note": "Step 25, the so-what test: link every piece of information to why the reader should care", "primary": true}, {"vid": "qPb2659z8jQ", "t": 619, "note": "HBR opening analyzed: destabilizing condition, then consequence, then solution; conceptual vs practical problems", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 579, "note": "Squirrel example: opening must challenge the reader's belief so they can't shrug 'so what'", "primary": false}, {"vid": "ePQoPNHZ7UY", "t": 619, "note": "Three steps: state condition with 'but', pass it through so-what to get consequence, keep them close", "primary": true}, {"vid": "ePQoPNHZ7UY", "t": 892, "note": "Intro formula: status quo, then problem made of condition and consequence", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Practical vs conceptual problems", "hits": [{"vid": "CSkWxm3flEQ", "t": 261, "note": "Ideas as solutions: practical problems change actions, conceptual problems replace an old idea", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 750, "note": "Pinpoint reader pain; TOC as bridge shows actions for practical problem", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 2137, "note": "Dan Koe wrote an ideas book but sold it as practical problem-solving", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 433, "note": "Even in the world of ideas we solve conceptual problems: readers hit a wall of understanding", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 584, "note": "Practical problem changes behavior, conceptual problem changes thinking upstream of behavior", "primary": true}, {"vid": "kiIGwqwc49Q", "t": 1153, "note": "Genre goals: better understanding or solving a practical problem by changing behavior", "primary": false}, {"vid": "qPb2659z8jQ", "t": 619, "note": "Conceptual problem = misunderstanding; conceptual problems are upstream of practical ones (HBR example)", "primary": true}, {"vid": "ePQoPNHZ7UY", "t": 851, "note": "Two kinds of solutions: practical gives actions, conceptual gives understanding", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Language of instability (but, however)", "hits": [{"vid": "ePQoPNHZ7UY", "t": 524, "note": "Problem statement points to instability of what seemed stable; 'but' example", "primary": false}, {"vid": "OHfMQeZqo60", "t": 274, "note": "Martini glass uses and, also; problems use but, however, by contrast to signal value", "primary": true}, {"vid": "OHfMQeZqo60", "t": 1297, "note": "Principle: lead with problems; use language of tension and instability, not stasis", "primary": false}, {"vid": "VkXMlrvq29o", "t": 1009, "note": "But, however, although signal instability and contrast, catnip for curious brains", "primary": true}, {"vid": "VrxufNaORhU", "t": 436, "note": "Readers want to move from stability to instability, not uncertainty to certainty", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Martini glass / school essay", "hits": [{"vid": "OHfMQeZqo60", "t": 52, "note": "Introduces the martini glass model: open wide with background, great for teachers, bad for readers", "primary": true}, {"vid": "OHfMQeZqo60", "t": 136, "note": "Template solves the teacher's grading problem; first flaw is imposing form top-down", "primary": true}, {"vid": "OHfMQeZqo60", "t": 215, "note": "Second flaw: readers scan for value in problems, martini glass signals continuity and stasis", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 290, "note": "School's background-to-thesis, inverted triangle, and gap-to-niche introductions", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 447, "note": "Inverted triangle is a pile of information; use common ground, problem, solution instead", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1519, "note": "Writers go general to specific then drop the reader; weave specifics back into the thread", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Point sentence at the end of the introduction", "hits": [{"vid": "bBg7GyIfn0A", "t": 448, "note": "Find the one sentence readers must accept and move it to the end of the introduction", "primary": true}, {"vid": "iTZt1_eocUg", "t": 2123, "note": "Readers expect the point at the end of the beginning; it should carry repeated key concepts", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 503, "note": "Synthesize a crisp point sentence; place it point-first at end of intro, or point-last with preview", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 1391, "note": "A point sentence in the index position must be something someone could disagree with", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Claim: significant, non-obvious, debatable / falsifiable", "hits": [{"vid": "sHclRP3xJK8", "t": 480, "note": "A claim is a truth claim that makes readers want to know more; 'water is wet' fails", "primary": false}, {"vid": "sHclRP3xJK8", "t": 517, "note": "Three features of a claim: significant, non-obvious, debatable; then evidence and counterarguments", "primary": true}, {"vid": "hWHB2noYItY", "t": 798, "note": "An idea is only an idea if someone could argue against it", "primary": false}, {"vid": "iCaX5cZ6roo", "t": 565, "note": "Claim defined as falsifiable statement; water vs Gatorade example of a real claim", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 1391, "note": "Test for a level-four point: someone else could disagree, i.e. falsifiable", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Claim, evidence, warrant / point, reason, evidence", "hits": [{"vid": "jmUlhEAS6GE", "t": 3863, "note": "Every idea has three parts: truth claim, evidence, and warrant explaining how evidence supports it", "primary": true}, {"vid": "iCaX5cZ6roo", "t": 622, "note": "Defines evidence the reader finds credible and warrant as logical bridge; climate example", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 1183, "note": "Slotting ideas into point-evidence structure exposes logical gaps; Orwell and AI example", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Hedges and boosters / certainty calibration", "hits": [{"vid": "sHclRP3xJK8", "t": 571, "note": "Address critics before moving on; academic writing is criticized for too many hedges", "primary": false}, {"vid": "sHclRP3xJK8", "t": 643, "note": "Adjust claim strength with hedges (sometimes, generally) or boosters (absolutely, certainly)", "primary": true}, {"vid": "hWHB2noYItY", "t": 733, "note": "For conversation-sparking books avoid hedging; make the boldest case", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 2005, "note": "Balance: modulate claims with qualifiers, but don't be too hedgy either", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 3720, "note": "Hedges like perhaps, seems, could be modulate confidence; balance confident vs arrogant", "primary": true}, {"vid": "jmUlhEAS6GE", "t": 3818, "note": "Too many hedges undermine you outside academia; too much confidence sounds arrogant", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1818, "note": "Certainty check: scale from hedged to strident with well-calibrated in the middle", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1928, "note": "Worked example of over-hedged vs calibrated sentence; fix by choosing verb and narrowing noun", "primary": true}], "dropped": 0}, {"group": "Value", "name": "Three standard objections", "hits": [{"vid": "jmUlhEAS6GE", "t": 913, "note": "Anticipate objections; beat readers to them; writing as telepathy", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 3428, "note": "Step 21: only three objections ever: other causes, counterexamples, different definitions", "primary": true}, {"vid": "kiIGwqwc49Q", "t": 1408, "note": "Address objections and reservations step by step on reader's terms", "primary": false}], "dropped": 0}, {"group": "Value", "name": "3V: Vow, Victim, Villain", "hits": [{"vid": "MTWhCW33mAw", "t": 414, "note": "Test your pitch on strangers, freeze the line as subtitle; that promise is the vow", "primary": true}, {"vid": "MTWhCW33mAw", "t": 725, "note": "Second V is the victim: the specific person in pain; then pick a fight", "primary": true}, {"vid": "MTWhCW33mAw", "t": 831, "note": "Villain examples: writing slop, Bad Therapy; a named enemy makes the message magnetic", "primary": false}, {"vid": "MTWhCW33mAw", "t": 882, "note": "How to pick a villain: name what the reader already hates, call it out plainly", "primary": true}], "dropped": 0}, {"group": "Value", "name": "Six types of nonfiction books", "hits": [{"vid": "hWHB2noYItY", "t": 286, "note": "The personal brand builder: 'I wrote the book on that'; start from the five W's", "primary": true}, {"vid": "hWHB2noYItY", "t": 653, "note": "The new authority: offers an alternative to the dominant view, readers buy copies to share", "primary": true}, {"vid": "hWHB2noYItY", "t": 1100, "note": "The lead getter: short actionable guide solving one urgent problem, positions you as expert", "primary": true}, {"vid": "hWHB2noYItY", "t": 1495, "note": "The booking agent: built for reach around a spreadable message, gets you invited to speak", "primary": false}, {"vid": "hWHB2noYItY", "t": 1859, "note": "The legacy book: capture your lessons for one person, not for virality or leads", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Chapter titles as promises", "hits": [{"vid": "CSkWxm3flEQ", "t": 204, "note": "Dan Koe's vague chapter titles; name each chapter as the promise of what reader learns", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 432, "note": "A chapter is a promise readers trade attention for; abstract titles break trust", "primary": true}], "dropped": 0}, {"group": "Value", "name": "Purpose chain / table of contents as bridge", "hits": [{"vid": "hWHB2noYItY", "t": 778, "note": "Build a bridge from where readers are: stories, examples, analogies, objections as stones", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 204, "note": "Chapter titles should promise what readers learn; vague TOC loses trust", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 310, "note": "Fill the table of contents with promises; turn vague titles into learning goals", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 387, "note": "Takeaways in the TOC let readers decide; a chapter solves a problem, not gives ideas", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 750, "note": "Purpose chain: goal, who must read it, their pain, TOC as bridge, then filter every idea", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 1387, "note": "Book has a table of contents, chapter needs a table of ideas; think in fractals", "primary": false}, {"vid": "ED_LXx3Hzak", "t": 1144, "note": "Don't debate readers; bridge from what they care about to what you show them", "primary": false}], "dropped": 0}, {"group": "Value", "name": "Text as a stage / limit the cast", "hits": [{"vid": "0-YMN4Z-H_0", "t": 317, "note": "Subject position is a spotlight; passive puts receiver in the spotlight", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 1699, "note": "Text as stage: paragraphs are scenes with 2-4 characters; subject is in spotlight; 'you' puts reader on stage", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 1900, "note": "Put the idea, e.g. the brain, in subject; 'you' as subject is rude", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 2662, "note": "Varying for variety makes readers work; only two or three characters on stage at once", "primary": true}, {"vid": "jmUlhEAS6GE", "t": 2899, "note": "Random characters entering the stage; organize subjects around reader problems", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 794, "note": "Text as play: variation introduces too many characters; limit the cast", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 950, "note": "Subject is the spotlight; dog/cat sentences; consistent subject gives a point of view", "primary": true}, {"vid": "iTZt1_eocUg", "t": 124, "note": "Characters center stage: subject position is like center stage or middle of the frame", "primary": false}, {"vid": "LAmzkEyt60E", "t": 316, "note": "Passage has a clear cast of Romanovs; movie poster test for abstraction", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Index and discussion (fractal)", "hits": [{"vid": "CSkWxm3flEQ", "t": 1272, "note": "Context first, meaning second; every unit of discourse needs an index section at the start", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 1353, "note": "Underline the main point, move it to the index; think in fractals; uneven U ends more general", "primary": true}, {"vid": "iTZt1_eocUg", "t": 2527, "note": "Index, discussion, wrap-up recur at every level from sentences to books; short then long", "primary": true}, {"vid": "n1CrHXxcfbA", "t": 445, "note": "Sentence-level index position: later topics link back to the emphasized information", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 500, "note": "Index sets the context for interpretation; one to three sentences; readers see it intuitively", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 732, "note": "Skim test: read only index positions and check they tell a coherent story", "primary": false}, {"vid": "VrxufNaORhU", "t": 1095, "note": "Index holds high-level concept, discussion pays it off; skim test as a reverse outline", "primary": false}, {"vid": "VrxufNaORhU", "t": 1327, "note": "Index positions are the major turns on the reader's route to the destination", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 1033, "note": "Missing index clause makes a passage incoherent; adding an umbrella clause snaps it into place", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 601, "note": "Point-last sections still need an index preview so the conclusion feels inevitable", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 906, "note": "Extract each section's point and put it in the index position at the top", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1391, "note": "Index point must be falsifiable; then progress down through levels toward evidence", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Key terms / topic strings / constellation", "hits": [{"vid": "qPb2659z8jQ", "t": 378, "note": "Annotates HBR opening: red key terms track the problem; 'understanding' in subject position", "primary": false}, {"vid": "qPb2659z8jQ", "t": 730, "note": "Defines topic string: same entity kept in subject position, camera-shot metaphor", "primary": true}, {"vid": "bBg7GyIfn0A", "t": 879, "note": "Build coherence with key terms: pick a section and identify the major terms readers must accept", "primary": false}, {"vid": "iTZt1_eocUg", "t": 2123, "note": "Put key terms in section headings and repeat them in the point sentence", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1314, "note": "Shows topic string pattern (Truman repeated) making passage clean and organized", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 806, "note": "Defines key term as preview of concepts; constellation of terms shown in Frazer passage", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 897, "note": "Color-coded topic strings: nouns in discussion link back to concepts in the index", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 951, "note": "Everything in the discussion links back to the index; that is a key term", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 1231, "note": "Repeat key terms or close analogs rather than synonyms so readers snap info into structure", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 642, "note": "Key terms saved for end of point sentence; each gets a section, like notes in a chord", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Uneven U / five levels of specificity", "hits": [{"vid": "CSkWxm3flEQ", "t": 1443, "note": "Introduces uneven U from Eric Hayot: start specific, go to evidence, end more general", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 1046, "note": "Five levels of specificity from abstract level five down to raw evidence at the floor", "primary": false}, {"vid": "2ToJcKiQWBc", "t": 1091, "note": "End on a different level than you began to give the essay forward thrust", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1298, "note": "Full walkthrough: five levels, begin at level four, descend through three and two to evidence", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 1572, "note": "Return to the point then push off to level five, linking the section to the thesis", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Hit-and-run quotation", "hits": [{"vid": "6HPNb0tiDNg", "t": 1487, "note": "Don't drop readers at the evidence; names the hit-and-run quotation from an academic writing book", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Four signals of coherence; cohesion vs coherence", "hits": [{"vid": "CSkWxm3flEQ", "t": 957, "note": "Names coherence and cohesion; 3D cube puzzle: pieces must connect to form macro structure", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 1061, "note": "Losing coherence at any level of resolution creates gaps between ideas", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 879, "note": "Coherence in nonfiction is built through key terms; make writing about one specific thing", "primary": false}, {"vid": "iTZt1_eocUg", "t": 907, "note": "Jigsaw metaphor: cohesion is pieces fitting, coherence is the unified picture", "primary": true}, {"vid": "iTZt1_eocUg", "t": 1962, "note": "Coherence is a reader experience; introduces four signals, starting with clear section boundaries", "primary": true}, {"vid": "iTZt1_eocUg", "t": 2123, "note": "Signals two to four: short intro segment, point sentence at its end, repeated key concepts", "primary": true}, {"vid": "mQ02Vwg-Uuo", "t": 501, "note": "Coherence is not a property of text but emerges in the reader; three kinds of structure", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Private, contextual, textual structure (number series)", "hits": [{"vid": "mQ02Vwg-Uuo", "t": 345, "note": "Three number series: primes, Fibonacci, mother's phone number; writing like you think is opaque", "primary": true}, {"vid": "mQ02Vwg-Uuo", "t": 614, "note": "Phone number was private structure; readers posit a pattern you didn't intend, causes metadiscourse", "primary": false}, {"vid": "mQ02Vwg-Uuo", "t": 729, "note": "Primes are contextual structure like genre; Fibonacci is textual structure readers see in the text", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Metadiscourse / signposting", "hits": [{"vid": "_X0UERlwz7Y", "t": 870, "note": "Defines metadiscourse as writing about writing, signposting; unnecessary in writing unlike speech", "primary": true}, {"vid": "LAmzkEyt60E", "t": 1057, "note": "Use transitions like 'for example' sparingly, only to help readers navigate macro structure", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 1299, "note": "Expand pattern to sections with first, second, third signposts linking back to introduction", "primary": false}, {"vid": "mQ02Vwg-Uuo", "t": 614, "note": "Private structure opaque to readers produces heavy metadiscourse; writer fills logical gaps", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Grice's maxims", "hits": [{"vid": "CSkWxm3flEQ", "t": 1111, "note": "Readers assume ideas cohere and won't allow gaps; orphaned ideas in Dan Koe's book", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 1199, "note": "Readers assume side-by-side items are related; fix with logical bridges and verbs for actions", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Conclusion: push off, end higher", "hits": [{"vid": "2ToJcKiQWBc", "t": 1118, "note": "Conclusion shouldn't say 'told you so'; push off the solution into a broader discussion", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 950, "note": "Transitions between sections round up the point and push off; sparing questions work", "primary": false}, {"vid": "6HPNb0tiDNg", "t": 1620, "note": "End of section links back up from level four to level five, the larger thesis question", "primary": true}, {"vid": "6HPNb0tiDNg", "t": 1771, "note": "Weave evidence back into the point, then push off to a more general level", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Title: four intrigue / curiosity triggers", "hits": [{"vid": "wXF_O741o6I", "t": 234, "note": "Headline is the first line; it must open curiosity loops; introduces four curiosity strategies", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 84, "note": "Avoid cryptic inside-joke titles; design titles using psychology-of-intrigue research", "primary": true}, {"vid": "2ToJcKiQWBc", "t": 175, "note": "Title format: eye-catching hook plus three nouns matching the piece's key concepts", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Opening image / opening number (CNF)", "hits": [{"vid": "DkigGUpCR1I", "t": 370, "note": "Opening image of pelicans and surfers: everything opens out of it", "primary": false}, {"vid": "DkigGUpCR1I", "t": 427, "note": "Opening as metaphor and opening number introducing all characters and themes", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Foreground vs background (narrative)", "hits": [{"vid": "ED_LXx3Hzak", "t": 339, "note": "Introduces foreground and background technique for sidestepping the exposition problem", "primary": false}, {"vid": "ED_LXx3Hzak", "t": 537, "note": "Foreground holds what you personally saw; background holds research, stats, definitions", "primary": true}], "dropped": 0}, {"group": "Structure", "name": "Zadie Smith's six-arrow rectangle", "hits": [{"vid": "Jhchk10LlRk", "t": 86, "note": "Zadie Smith's Cambridge story: 'This is not an essay'; discovering the framework", "primary": false}, {"vid": "Jhchk10LlRk", "t": 188, "note": "Impersonal essay explained, then the rectangle: six arrows, title in center, write 1 and 6 first", "primary": true}, {"vid": "Jhchk10LlRk", "t": 409, "note": "Arrow three: devil's advocate, steel man opposition, acknowledge limits", "primary": false}, {"vid": "Jhchk10LlRk", "t": 530, "note": "Rectangle removes every decision except the next; impersonal essay reaches general readers", "primary": false}], "dropped": 0}, {"group": "Structure", "name": "Bilbo moment / AAB examples", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 2499, "note": "Bilbo moment: like Gandalf, secure the reader's commitment with a comfortable start", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 2618, "note": "Bilbo effect: order examples simple to complex, literal to metaphorical, then build", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Characters as subjects, actions as verbs", "hits": [{"vid": "wXF_O741o6I", "t": 582, "note": "Passive voice and 'be' verbs suck life out; readers want characters in subjects, actions in verbs", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 2004, "note": "Place specific actions in verbs, not nouns; verb is the heart of the sentence", "primary": false}, {"vid": "G-Sl0-PZv2Q", "t": 2884, "note": "Zombie nouns hide actions; fix by putting real characters as subjects and actions as verbs", "primary": false}, {"vid": "bBg7GyIfn0A", "t": 1264, "note": "Recap: clear characters in subject plus clear actions in verb make a core clause", "primary": false}, {"vid": "iTZt1_eocUg", "t": 124, "note": "Jack and the giant example; subject position is center stage, put main characters there", "primary": true}, {"vid": "iTZt1_eocUg", "t": 464, "note": "Revising nominalized sentence back to character-subject and action-verb for clarity", "primary": false}, {"vid": "iTZt1_eocUg", "t": 561, "note": "Flesh-and-blood subject makes sentence clearer; familiar nominalizations can act as characters", "primary": false}, {"vid": "LAmzkEyt60E", "t": 1112, "note": "Empty verb signals hidden action; ask 'who does what' and move the boyars into the subject", "primary": true}, {"vid": "n1CrHXxcfbA", "t": 215, "note": "Bees and honey rewrite shows characters and actions are variable; the principle stated", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1388, "note": "Summary of the two principles: characters in subject, actions in verb, old before new", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Zombie nouns / nominalizations", "hits": [{"vid": "lvMkX6OX4dg", "t": 172, "note": "Zombie noun examples and three-step fix: find action, put in verb, assign character subject", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 2884, "note": "Zombie nouns defined; fix by putting characters in subjects and actions in verbs", "primary": false}, {"vid": "iTZt1_eocUg", "t": 294, "note": "Names nominalization; explains four good uses of nominalizations", "primary": true}, {"vid": "iTZt1_eocUg", "t": 561, "note": "Fourth use: familiar nominalizations act as characters; distinguishing which to revise", "primary": false}, {"vid": "nsa44tXal7A", "t": 814, "note": "Uses a nominalization as direct object because transitive verb needs an object", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Empty verbs", "hits": [{"vid": "wXF_O741o6I", "t": 582, "note": "Passive puts focus on flabby 'be' verb; agent in subject, action in verb", "primary": false}, {"vid": "iTZt1_eocUg", "t": 256, "note": "Nominalizing actions forces vague flabby verbs like undertaken, took place", "primary": false}, {"vid": "LAmzkEyt60E", "t": 631, "note": "Empty verbs like 'resulted in' signal action hiding in a noun; restore it to the verb", "primary": true}, {"vid": "LAmzkEyt60E", "t": 1112, "note": "Fix 'resulted in' by asking who does what; boyars disputing goes in subject", "primary": true}, {"vid": "n1CrHXxcfbA", "t": 1042, "note": "Editing an empty verb: package points, then 'concluded' carries the action", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Short subject, verb early (tunnel / locomotive)", "hits": [{"vid": "lvMkX6OX4dg", "t": 42, "note": "Sets up the holding-your-breath-through-a-tunnel childhood game as the analogy", "primary": false}, {"vid": "lvMkX6OX4dg", "t": 102, "note": "Verb is the end of the tunnel; readers hold their breath until it arrives, so put it early", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 91, "note": "Locomotive effect: 15 words between subject and verb strains memory; put both up front", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Topic position and stress position", "hits": [{"vid": "-mEdJPYahxo", "t": 527, "note": "Sentence end is prime real estate, a reason not to end on a preposition", "primary": false}, {"vid": "-mEdJPYahxo", "t": 648, "note": "Give the prime real estate at sentence end to what matters most; brief mention", "primary": false}, {"vid": "0-YMN4Z-H_0", "t": 228, "note": "Names the sentence end as the stress position; restaurant passive voice example", "primary": false}, {"vid": "0-YMN4Z-H_0", "t": 351, "note": "Award-show example: emphasis falls at the end; passive puts key word in stress position", "primary": true}, {"vid": "0-YMN4Z-H_0", "t": 906, "note": "Adverb at sentence end feels stronger; end words receive greater emphasis", "primary": false}, {"vid": "0-YMN4Z-H_0", "t": 963, "note": "To highlight an adverb or key idea, place it at the end in the stress position", "primary": false}, {"vid": "IqPLeyTahLs", "t": 390, "note": "Repetition in the topic position helps readers track; party conversation and camera analogies", "primary": false}, {"vid": "IqPLeyTahLs", "t": 801, "note": "Recap: emphasis-worthy information in stress position, main characters in topic position", "primary": false}, {"vid": "j1JRSan9CYg", "t": 100, "note": "Readers read left to right, so sentence start is the topic position; bees versus honey", "primary": true}, {"vid": "j1JRSan9CYg", "t": 347, "note": "Passive verb lets you move what clients care about into the topic position", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 154, "note": "Defines topic as start through subject and comment as everything after it", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 261, "note": "Familiar context at the start, new emphasis-worthy information at the end in the comment", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 417, "note": "Comment position gets emphasis and controls interpretation; he calls it the index position", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1066, "note": "Overloaded subject details moved to the end of the sentence into the comment", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1155, "note": "Heavy information moved from topic position to the end where readers manage it", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1264, "note": "Backward-linking context in the topic position produces clean patterns of reference", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1337, "note": "Zoomed out: short subjects and topics all linking back to Truman or political issues", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1388, "note": "Summary of the two principles including familiar topics first, new information in comment", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 120, "note": "Happiness passage contrast; topic as doorstep, comment as room the reader walks into", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Old to new information flow", "hits": [{"vid": "lvMkX6OX4dg", "t": 603, "note": "Defines old to new with aluminum example; sentences push off each other like a swimmer", "primary": true}, {"vid": "lvMkX6OX4dg", "t": 713, "note": "Begin sentences with old information, end with new, so readers experience flow", "primary": false}, {"vid": "_X0UERlwz7Y", "t": 557, "note": "Sentences as relay runners: old information first, new unanticipated information last", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 316, "note": "Sentences with only old information are closed loops; only new information informs", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 423, "note": "Understandable sentences blend new scores with familiar context; pair new with known", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 583, "note": "Pen example: same information reordered so new ends set expectations for next sentences", "primary": true}, {"vid": "MtbfC3gQNNE", "t": 720, "note": "Readers expect familiar first; old to new creates clear focus and coherent discourse", "primary": true}, {"vid": "MtbfC3gQNNE", "t": 861, "note": "Bitcoin passage: spot where active sentences break old to new flow", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 939, "note": "Passive voice exists to move old information into the subject position", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 1040, "note": "German proverb: beginning and end shake hands; old to new is one tool among several", "primary": false}, {"vid": "iTZt1_eocUg", "t": 1446, "note": "Long phrases and new technical terms belong at sentence end; short subject first", "primary": false}, {"vid": "LAmzkEyt60E", "t": 631, "note": "Live edit: keeps successor at the sentence start to preserve old to new flow", "primary": false}, {"vid": "LAmzkEyt60E", "t": 1194, "note": "Connector 'because' forces old information to the end; rearranging clauses to fix it", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 215, "note": "Second level of organization: familiar context at the start, emphasis-worthy new information in comment", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 366, "note": "New information goes at the end because it controls the rest of the passage", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 819, "note": "Truman edit: treat Truman as old information, move new information to sentence end", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1264, "note": "Organizing old to new with backward-linking context produces clean chains of reference", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 1372, "note": "Summary: readers expect backward-linking context first, new complex information at the end", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 180, "note": "Csikszentmihalyi passage: old information in topic position, new information in the comment", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 1299, "note": "Old to new linking pattern nested inside a larger theme-preview section structure", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Relay race / baton / shaking hands (sentence handoff)", "hits": [{"vid": "lvMkX6OX4dg", "t": 603, "note": "Sentences push off each other like a swimmer; each picks up where the last left off", "primary": false}, {"vid": "_X0UERlwz7Y", "t": 557, "note": "Sentences act like runners in a relay race, one picking up where the other left off", "primary": true}, {"vid": "MtbfC3gQNNE", "t": 1040, "note": "German proverb for flow: the beginning and end shake hands with each other", "primary": false}, {"vid": "IqPLeyTahLs", "t": 295, "note": "Sentence end lingers in memory; next sentence takes the baton; Sarah and mother example", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Passive voice as a tool", "hits": [{"vid": "wXF_O741o6I", "t": 382, "note": "Defines active vs passive via agent, process, goal; two problems passive causes", "primary": true}, {"vid": "wXF_O741o6I", "t": 667, "note": "Default to active but passive is a tool; David Foster Wallace 5% quote", "primary": false}, {"vid": "_X0UERlwz7Y", "t": 449, "note": "Passive makes passage flow by keeping topic and linking to next sentence", "primary": false}, {"vid": "0-YMN4Z-H_0", "t": 228, "note": "Five situations to use passive; how to identify it; Strunk and White's false examples", "primary": true}, {"vid": "MtbfC3gQNNE", "t": 785, "note": "Passive as tool for flow; DFW quote; 5% of cases", "primary": false}, {"vid": "MtbfC3gQNNE", "t": 939, "note": "Passive lets old information sit in subject position for flow", "primary": false}, {"vid": "iTZt1_eocUg", "t": 836, "note": "Passive lines up end of one sentence with start of next; bus-taxi effect", "primary": false}, {"vid": "LAmzkEyt60E", "t": 346, "note": "Uses passive to move recurring characters to sentence openings", "primary": false}, {"vid": "LAmzkEyt60E", "t": 420, "note": "Passive shifts information: concrete start, abstract end; Romanov example", "primary": false}, {"vid": "IOCOw72YjZk", "t": 267, "note": "Passive not weak; tool for controlling agency; Darwin's 'are being evolved'", "primary": true}, {"vid": "IOCOw72YjZk", "t": 508, "note": "Passive gave Darwin breathing room; active and passive are writer decisions, not rules", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Movie-poster test", "hits": [{"vid": "LAmzkEyt60E", "t": 23, "note": "Ask who goes on the movie poster; Mary-pie sentences show the subject tells whose story it is", "primary": true}, {"vid": "LAmzkEyt60E", "t": 316, "note": "Applies the poster test to the Romanov passage: abstractions vs the real cast of characters", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "First 7–8 words diagnostic", "hits": [{"vid": "iTZt1_eocUg", "t": 1099, "note": "Three-step method: underline first seven or eight words of each sentence up to verb", "primary": true}, {"vid": "LAmzkEyt60E", "t": 269, "note": "Reader attention trained on sentence start; underline first seven-eight words to diagnose", "primary": true}, {"vid": "LAmzkEyt60E", "t": 346, "note": "Opening words should share concrete characters across sentences; uses passive to do it", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Reader-question test (bees make honey)", "hits": [{"vid": "jmUlhEAS6GE", "t": 1199, "note": "Brief mention: content must perform reader functions and answer reader questions", "primary": false}, {"vid": "j1JRSan9CYg", "t": 0, "note": "Bees make honey vs honey is made by bees; exposes shorter and active-voice assumptions", "primary": false}, {"vid": "j1JRSan9CYg", "t": 236, "note": "Longer passive sentence can be better because it is more valuable to certain readers", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Four topic-progression patterns", "hits": [{"vid": "cayUBPHB1HQ", "t": 413, "note": "Linking pattern: reader steps room to room, each clause picks up the previous comment", "primary": true}, {"vid": "cayUBPHB1HQ", "t": 624, "note": "Portland coffee passage shows the linking pattern going off the rails without a unifying topic", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 961, "note": "Umbrella category on top lends coherence; pressed-leaves passage with the index clause missing", "primary": false}, {"vid": "cayUBPHB1HQ", "t": 1033, "note": "Missing index clause makes varied topics incoherent; adding the umbrella sentence snaps them into place", "primary": true}, {"vid": "cayUBPHB1HQ", "t": 1177, "note": "Theme preview: first comment sets up A, B, C, which successive clauses develop in order", "primary": true}, {"vid": "cayUBPHB1HQ", "t": 1299, "note": "Expand patterns to whole sections and nest them at different levels of resolution", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Mental briefcase / working memory", "hits": [{"vid": "IqPLeyTahLs", "t": 256, "note": "Chunking into a mental briefcase; first item is sentence ending echoed in next start", "primary": true}, {"vid": "IqPLeyTahLs", "t": 520, "note": "Second item, consistent topic; third item, sensory impressions", "primary": true}, {"vid": "IqPLeyTahLs", "t": 692, "note": "Fourth item, expectations that pull readers forward; 'shocking' example", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Concrete language / stub your toe / ladder of abstraction", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 678, "note": "Ladder of abstraction: concrete images you can stub your toe on versus abstract ideas; Gatsby green light", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 729, "note": "Balance ideas by moving up and down the ladder of abstraction", "primary": false}, {"vid": "qPb2659z8jQ", "t": 828, "note": "Ground every abstraction in something the reader could stub their toe on; vision brain is older", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Intuition pump", "hits": [{"vid": "qPb2659z8jQ", "t": 1695, "note": "Intuition pump vs example: puts reader in detective position; cockpit and casino metaphors", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Since vs because; ', which' clauses; -ing reductions", "hits": [{"vid": "LAmzkEyt60E", "t": 582, "note": "Move verb forward as nonfinite -ing clause to give prominence to first clause", "primary": false}, {"vid": "LAmzkEyt60E", "t": 1219, "note": "Since vs because: since links backward to known information while keeping cause-effect", "primary": true}, {"vid": "FcUtF0UdPsg", "t": 644, "note": "Comma-which non-restrictive clause is the structure for definitions", "primary": false}, {"vid": "n1CrHXxcfbA", "t": 586, "note": "Comma-which clauses for definition, effect, interpretation; reduce them to -ing", "primary": true}], "dropped": 0}, {"group": "Sentence", "name": "Strategic repetition; don't vary for variety", "hits": [{"vid": "_X0UERlwz7Y", "t": 335, "note": "Repeating the topic helps readers see the passage globally despite sentence-level advice", "primary": false}, {"vid": "jmUlhEAS6GE", "t": 2576, "note": "Flow from organization; first trick keep subjects consistent; avoiding repetition is a myth", "primary": true}, {"vid": "bBg7GyIfn0A", "t": 740, "note": "Editors tell you to vary, but repetition is the hack that makes essays easy to follow", "primary": false}, {"vid": "IqPLeyTahLs", "t": 348, "note": "Topic concept goes against 'vary your sentences' advice", "primary": true}, {"vid": "LAmzkEyt60E", "t": 0, "note": "Your writing is unclear because you vary structure to avoid sounding repetitive", "primary": false}, {"vid": "LAmzkEyt60E", "t": 785, "note": "Strategic repetition applied to Romanov passage; noun phrases as suitcases", "primary": true}, {"vid": "LAmzkEyt60E", "t": 875, "note": "Applying strategic repetition: carry tsars from previous sentence end to next start", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Sentence length myth (Provost)", "hits": [{"vid": "nsa44tXal7A", "t": 135, "note": "Sentence length does not matter if you shape sentences properly; compression is the point", "primary": false}, {"vid": "IOCOw72YjZk", "t": 42, "note": "Reads the Gary Provost sentence-length meme aloud", "primary": false}, {"vid": "IOCOw72YjZk", "t": 78, "note": "Debunks Provost meme: sentence length has no relation to readability or music", "primary": true}, {"vid": "gaqIcDkTakA", "t": 1808, "note": "Brief mention: vary-sentence-length Provost meme as example of bogus feedback", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Jargon as membership card", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 304, "note": "'Prior' versus 'assumption', 'stochastic' versus 'random' signal community membership beyond information", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 1023, "note": "Avoiding a group's insider lingo gets you excluded, however good your ideas", "primary": false}, {"vid": "IOCOw72YjZk", "t": 762, "note": "We code-switch to mark group membership; stochastic is a membership card, not a $50 word", "primary": true}, {"vid": "IOCOw72YjZk", "t": 860, "note": "Jargon for the right audience isn't bad writing; skilled writers switch registers", "primary": false}], "dropped": 0}, {"group": "Sentence", "name": "Author-splaining / ellipsis in dialogue", "hits": [{"vid": "30Ic686MRZU", "t": 300, "note": "Defines author-splaining, tells you to delete -ly adverbs after 'said' and trust readers", "primary": true}, {"vid": "30Ic686MRZU", "t": 1146, "note": "Names ellipsis: strategically leaving things out of dialogue, There Will Be Blood example", "primary": true}], "dropped": 0}, {"group": "Compression", "name": "Filler, doublets, redundancy", "hits": [{"vid": "nsa44tXal7A", "t": 0, "note": "Why writing like you speak fails; readers want code-like efficiency; bloated sentence example", "primary": false}, {"vid": "nsa44tXal7A", "t": 117, "note": "Cuts 'each and every' and 'suggestion offered' as redundant in the example sentence", "primary": false}, {"vid": "nsa44tXal7A", "t": 156, "note": "Filler words like actually, certain, basically are throat clearing; example cleaned up", "primary": true}, {"vid": "nsa44tXal7A", "t": 339, "note": "Doublets explained: various and multiple, each and every; French-Latin pairing history", "primary": true}, {"vid": "nsa44tXal7A", "t": 438, "note": "Introduces three types of redundancy readers use to judge writers", "primary": false}, {"vid": "nsa44tXal7A", "t": 510, "note": "Redundant modifiers: ultimate result, suddenly astonished; cut them for precision", "primary": false}, {"vid": "nsa44tXal7A", "t": 581, "note": "Redundant categories, general implications spread across words; then find the exact word", "primary": true}], "dropped": 0}, {"group": "Compression", "name": "Affirmative over negative", "hits": [{"vid": "nsa44tXal7A", "t": 980, "note": "Negatives force readers to reverse the sentence; translation list and compounded-negative example", "primary": true}, {"vid": "nsa44tXal7A", "t": 1139, "note": "Rewrites negative clauses positive; lists implicitly negative words; exception when warning is the point", "primary": true}], "dropped": 0}, {"group": "Compression", "name": "Exact word (le mot juste)", "hits": [{"vid": "nsa44tXal7A", "t": 921, "note": "Replace clumsy spoken phrases with one exact word; look through words to ideas", "primary": true}], "dropped": 0}, {"group": "Compression", "name": "Punctuation X-ray / minimalism (McCarthy)", "hits": [{"vid": "qPb2659z8jQ", "t": 144, "note": "Look only at punctuation to see sentence construction; McCarthy cuts every unneeded mark, word, section", "primary": true}, {"vid": "nsa44tXal7A", "t": 284, "note": "Cut verbal static words; be ruthless paring down to achieve clarity through minimalism", "primary": false}], "dropped": 0}, {"group": "Compression", "name": "Em dash: emphasis, three uses", "hits": [{"vid": "FcUtF0UdPsg", "t": 151, "note": "Shows commas replaced by em dashes to unclog a sentence; read silently to feel emphasis", "primary": false}, {"vid": "FcUtF0UdPsg", "t": 335, "note": "Expert patterns: em dash pair for exemplification (Popova) and aside comment (Sinek)", "primary": true}, {"vid": "FcUtF0UdPsg", "t": 582, "note": "Careless usage: overusing em dashes for definitions dilutes their force, like 'however'", "primary": false}, {"vid": "FcUtF0UdPsg", "t": 708, "note": "Sums up: em dash pair for emphasis, parentheses for quieter asides", "primary": true}], "dropped": 0}, {"group": "Compression", "name": "Understate the serious, overstate the light", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 2323, "note": "Orwell's windowpane: best writing doesn't draw attention to itself, especially with heavy subjects", "primary": false}, {"vid": "G-Sl0-PZv2Q", "t": 2420, "note": "Let the weight of a serious story do the work; understate serious, overstate light", "primary": true}], "dropped": 0}, {"group": "Feedback", "name": "Early readers / community of practice", "hits": [{"vid": "jmUlhEAS6GE", "t": 4267, "note": "Test writing with real people, editors or beta readers; Paul Millerd connecting with audience", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1680, "note": "Defines early readers and community of practice with letter of response and trusted feedback", "primary": true}, {"vid": "gaqIcDkTakA", "t": 2017, "note": "Community of practice with shared practice solved voice and publishing problems without teaching", "primary": false}], "dropped": 0}, {"group": "Feedback", "name": "Letter of response / two readings / silent author", "hits": [{"vid": "gaqIcDkTakA", "t": 930, "note": "Seminar format: readings with assigned letters of response, brought into online cohort", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1022, "note": "Letter of response stage one: state what the essay is trying to do before criticizing", "primary": true}, {"vid": "gaqIcDkTakA", "t": 1093, "note": "Stage two: say what you would steal; only afterward any criticism", "primary": true}, {"vid": "gaqIcDkTakA", "t": 1320, "note": "Author listens silently as two letters are read; read essay twice to see how it works", "primary": true}, {"vid": "gaqIcDkTakA", "t": 1417, "note": "Body-scan analogy: locate exactly where boredom or pain lives in the text", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1478, "note": "Reading as craft analysis; sessions lengthened so authors could respond afterward", "primary": false}, {"vid": "gaqIcDkTakA", "t": 1733, "note": "Early readers and community of practice governed by letter-of-response guidelines", "primary": false}], "dropped": 0}, {"group": "Feedback", "name": "Reader feedback describes symptoms (friction)", "hits": [{"vid": "LAmzkEyt60E", "t": 204, "note": "Readers say unclear, dense, disorganized; not helpful diagnosis", "primary": false}, {"vid": "VkXMlrvq29o", "t": 729, "note": "Reader complaints describe friction between writer's thinking and reading patterns", "primary": true}, {"vid": "VrxufNaORhU", "t": 436, "note": "Feedback words describe symptoms not cause; friction between patterns; interference", "primary": true}], "dropped": 0}, {"group": "AI", "name": "AI cannot think / style is not a coat of paint", "hits": [{"vid": "JRyVJKj4z7E", "t": 640, "note": "AI tools are language machines, not thinking machines; can't show an organizing mind or set priorities", "primary": true}, {"vid": "JGSA6Wbbaxo", "t": 302, "note": "AI blends every voice into homogeneous slop; hiding AI phrases is tricking readers, not writing", "primary": false}, {"vid": "3kf9rRztJgA", "t": 213, "note": "Workflow one: dressing up AI outputs as your own is polishing a turd; source of inauthenticity", "primary": true}, {"vid": "3kf9rRztJgA", "t": 527, "note": "Workflow two treats style as a coat of paint over messy substance; explains why that fails", "primary": true}, {"vid": "3kf9rRztJgA", "t": 893, "note": "AI's window on the world is a funhouse mirror; better prompts don't fix it", "primary": false}], "dropped": 0}, {"group": "AI", "name": "Five skills AI will never replace", "hits": [{"vid": "JGSA6Wbbaxo", "t": 382, "note": "AI metaphors feel uncanny because AI is disembodied; human embodiment advantage", "primary": true}, {"vid": "JGSA6Wbbaxo", "t": 470, "note": "Metaphors We Live By: metaphors come from embodied experience, not decoration", "primary": false}, {"vid": "JGSA6Wbbaxo", "t": 828, "note": "Fourth skill, stakes: story of hard theory seminar where writing had consequences", "primary": false}, {"vid": "JGSA6Wbbaxo", "t": 939, "note": "Continues seminar story: struggle with original sources without summaries built depth", "primary": false}, {"vid": "JGSA6Wbbaxo", "t": 985, "note": "Asks what is lost when AI makes work easy; answer is stakes", "primary": false}, {"vid": "JGSA6Wbbaxo", "t": 1088, "note": "Accountability produces clarity; AI has no consequences; publish under your own name", "primary": true}, {"vid": "JGSA6Wbbaxo", "t": 1272, "note": "Fifth skill, whimsy: writing as play, Nussbaum's typewriter as transitional object", "primary": false}, {"vid": "JGSA6Wbbaxo", "t": 1464, "note": "Wraps up: AI optimized for average; being alive, embodied, at stake is your moat", "primary": true}], "dropped": 0}, {"group": "AI", "name": "AI as read-only navigation layer", "hits": [{"vid": "_ribgj7VIGc", "t": 1361, "note": "AI navigates his vault but never rewrites it; keeps the thinking yours, not the writing", "primary": true}, {"vid": "3kf9rRztJgA", "t": 1038, "note": "Uses AI only as a navigation layer over his notes, never for communicative writing", "primary": false}], "dropped": 0}, {"group": "Rhetoric", "name": "31 tools (alliteration, antithesis, polyptoton, diacope, epistrophe, prolepsis, congeries, synesthesia)", "hits": [{"vid": "G-Sl0-PZv2Q", "t": 640, "note": "Wraps up alliteration as sixth tool: alliterative lines sound true and memorable", "primary": false}, {"vid": "G-Sl0-PZv2Q", "t": 877, "note": "Defines antithesis: assert forcefully by inverting, covering what is and is not true", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 1198, "note": "Defines synesthesia with examples; urges mixing senses to ground abstract ideas", "primary": true}, {"vid": "G-Sl0-PZv2Q", "t": 1439, "note": "Defines epistrophe: repeating end phrase keeps readers on core message like a chorus", "primary": false}], "dropped": 0}, {"group": "Rhetoric", "name": "Ironic juxtaposition / kill your darlings", "hits": [{"vid": "wXF_O741o6I", "t": 68, "note": "Scott Adams blog post: key to persuasive writing is kill your darlings", "primary": false}, {"vid": "wXF_O741o6I", "t": 163, "note": "Kill your darlings means pruning extra words like a gardener so strong parts flower", "primary": true}], "dropped": 0}, {"group": "Academic", "name": "Scholar vs researcher; organizing mind", "hits": [{"vid": "JRyVJKj4z7E", "t": 193, "note": "Researcher vs scholar defined; scholars write lit review first; in a world of researchers be a scholar", "primary": true}, {"vid": "JRyVJKj4z7E", "t": 536, "note": "Bibliographic lit review makes you a scholar before researcher", "primary": false}, {"vid": "JRyVJKj4z7E", "t": 640, "note": "Lit review's key quality is an organizing mind: analyze, connect, set priorities", "primary": true}], "dropped": 0}, {"group": "Academic", "name": "Literature review: plot vs story, casting studies", "hits": [{"vid": "rC2O0J5k2eM", "t": 34, "note": "Sets up the Avengers example: the plot is the on-screen sequence of events", "primary": false}, {"vid": "rC2O0J5k2eM", "t": 126, "note": "Story is bigger than plot; listing studies under headings is plot, not story", "primary": true}, {"vid": "rC2O0J5k2eM", "t": 292, "note": "Cast studies as primary characters, allies, adversaries; cut sources that don't contribute", "primary": true}], "dropped": 0}, {"group": "Academic", "name": "Citations: simple syntax, personal language, present tense", "hits": [{"vid": "kTl79dinMBM", "t": 4, "note": "Sets up three research-backed style tips from 30,000 high-impact articles; rulebooks hurt citations", "primary": false}, {"vid": "kTl79dinMBM", "t": 283, "note": "Fewer function words means simpler sentences; personal language in intro and abstract boosts citations", "primary": true}, {"vid": "kTl79dinMBM", "t": 593, "note": "Tense is not time; present tense makes your research feel current and gets cited more", "primary": true}], "dropped": 0}, {"group": "Academic", "name": "Author function vs flesh-and-blood author / persona", "hits": [{"vid": "rC2O0J5k2eM", "t": 627, "note": "Contrasts author function 'I' inside text with flesh-and-blood author entering the story", "primary": true}, {"vid": "rC2O0J5k2eM", "t": 804, "note": "Second use of pronouns builds a persona readers like and trust, hence persuadable", "primary": false}, {"vid": "CSkWxm3flEQ", "t": 1590, "note": "Voice on the page is a persona made of sentences, not the real Dan Koe", "primary": true}, {"vid": "CSkWxm3flEQ", "t": 2005, "note": "Be intentional about the persona; the character in your book is separate from you", "primary": false}], "dropped": 0}];